@register(
    "astrbot_plugin_zhutian",
    "wuhen",
    "诸天万界修仙（Python 重构版）",
    "v0.1.0",
    "",
)
class ZhutianPlugin(Star):
    def __init__(self, context: Context, config: AstrBotConfig):
        super().__init__(context)
        self.config = config
        self.db = DataBase(StarTools.get_data_dir("zhutian") / "zhutian.db")
        self._last_cmd_ts: dict[str, float] = {}   # 同人指令去抖：防连发时整档互相覆盖（双倍签到/丢奖励）
        self.panel_dir = StarTools.get_data_dir("zhutian") / "panels"
        self.render_on = bool(config.get("RENDER_ENABLE", True))
        # shortcut: 数据表暂从插件目录读取（随代码分发），表多体积大后改放 StarTools 数据目录
        self.content = ContentStore(PLUGIN_DIR / "data")
        logger.info(f"[zhutian] 内容表 {len(self.content.tables)} 张已加载")
        # W8-B2b：精神位面（9 处 / 28 层）灌进元神模块
        loaded = ysh_mod.load_places(self.content.table("jingshen/精神宇宙") or [])
        logger.info(f"[zhutian] 精神位面 {loaded} 处已载入")
        # W8-B5 / B3：记忆命途、花粉路注册为第三轨（只进门槛与天堑）
        try:
            from .core import authority as _auth
            _auth.register_track(mem_mod.equivalent_level)
            _auth.register_track(flower_mod.equivalent_level)
        except Exception:
            pass
        self.whitelist_groups = [
            str(g) for g in (config.get("ACCESS_CONTROL", {}).get("WHITELIST_GROUPS") or [])
        ]
        # W8-F1：超管世界状态缓存（难度 / 修仙管理员 / 公告群 / 管理日志），
        # 启动时从 calamity_state["admin"] 灌入；只有 #选择难度 一类的指令会改写它。
        self._adm_state: dict = adm_mod.state_of({})
        self._adm_difficulty: str = adm_mod.DEFAULT_DIFFICULTY
        self._adm_flags: dict = adm_mod.DIFFICULTIES[self._adm_difficulty]
        self._legacy_import_report: dict | None = None

        # 物品索引：从指定类别表构建 名称→物品（同名以先出现者为准）
        self.item_index: dict[str, dict] = {}
        dupes = 0
        for t in ITEM_TABLES:
            table = self.content.table("item/" + t)
            if not isinstance(table, list):
                continue
            for e in table:
                if not isinstance(e, dict) or not e.get("name") or "class" not in e:
                    continue
                if e["name"] in self.item_index:
                    dupes += 1
                    continue
                self.item_index[e["name"]] = e
        # W8-C4：锻炉材料九维专用索引（item_index 中"材料列表"可能先占同名条目）
        self._furn_mats = {
            e["name"]: e for e in (self.content.table("item/锻造材料") or [])
            if isinstance(e, dict) and e.get("name")
        }
        # W8-D2：星阁官方拍品表（43 外场 / 36 内场），专用索引不进 item_index
        self._xg_pools = {
            "official": [e for e in (self.content.table("item/星阁拍卖行列表") or [])
                         if isinstance(e, dict) and e.get("name")],
            "inner": [e for e in (self.content.table("item/星阁内场拍卖行") or [])
                      if isinstance(e, dict) and e.get("name")],
        }
        self.shop_stock = [
            e for t in ("item/常驻", "item/限定")
            for e in (self.content.table(t) if isinstance(self.content.table(t), list) else [])
            if isinstance(e, dict) and e.get("name")
        ]
        logger.info(f"[zhutian] 物品索引 {len(self.item_index)} 条（去重 {dupes}），坊市货架 {len(self.shop_stock)} 件")

        # 仙宠图鉴按 id 索引（进阶形态 = id+1，对齐原版）
        self.pet_by_id = {
            int(e["id"]): e for e in self.item_index.values()
            if e.get("class") == "仙宠" and str(e.get("id") or "").isdigit()
        }

        # 秘境掉落池：材料/草药/丹药（稀有度门槛在掉落时过滤）
        self.drop_pool = [
            e for e in self.item_index.values()
            if e.get("class") in ("材料", "草药", "丹药")
        ]

        # 灵根（天资）表：原版 139 条，天资洗炼类丹药重摇用
        self.linggen_table = [
            e for e in (self.content.table("item/灵根列表") or [])
            if isinstance(e, dict) and e.get("name")
        ]

        # 职业经验表（occupation/experience.json 38 档）与职业名单
        self.occ_exp_table = [
            e for e in (self.content.table("occupation/experience") or [])
            if isinstance(e, dict) and e.get("id") is not None
        ]
        self.job_names = [
            str(e.get("name")) for e in (self.content.table("occupation/职业列表") or [])
            if isinstance(e, dict) and e.get("name")
        ]

        # 炼丹配方：原版 21 条；产物双轨判定（对齐原版 zhizuo_dan）
        # direct = 产物原丹有效果（修为/血量/血气/天资洗炼）→ 直接产出
        # quality = 凡品/极品/仙品 三档分档丹在索引（原版品质分档）→ 掷品质
        self.recipes = [
            r for r in (self.content.table("occupation/炼丹配方") or [])
            if isinstance(r, dict) and r.get("name")
        ]
        self.craft_mode: dict[str, str] = {}
        for r in self.recipes:
            name = r["name"]
            p = self.item_index.get(name)
            if p and (
                p.get("exp")
                or float(p.get("HPp") or 0) > 0
                or float(p.get("HP") or 0) > 1
                or float(p.get("xueqi") or 0) > 0
                or float(p.get("linggen") or 0) > 0
                or float(p.get("potential") or 0) > 0
                or float(p.get("heart") or 0) > 0
                or p.get("type") == "天资洗炼"
            ):
                self.craft_mode[name] = "direct"
            elif all(f"{q}{name}" in self.item_index for q in ("凡品", "极品", "仙品")):
                self.craft_mode[name] = "quality"
        self.craftable = [r for r in self.recipes if r["name"] in self.craft_mode]
        logger.info(f"[zhutian] 炼丹配方 {len(self.recipes)} 条，开放 {len(self.craftable)} 条")

        # 锻造图纸：原版 7 条，仅开放产物在索引的
        self.forge_recipes = [
            r for r in (self.content.table("occupation/装备图纸") or [])
            if isinstance(r, dict) and r.get("name") and r["name"] in self.item_index
        ]
        logger.info(f"[zhutian] 锻造图纸 {len(self.forge_recipes)} 条开放（原版 7 条）")

    async def initialize(self) -> None:
        await self.db.connect()
        try:
            self._adm_state = adm_mod.state_of(await self.db.get_calamity())
            self._adm_difficulty = adm_mod.difficulty_of(self._adm_state)
            self._adm_flags = adm_mod.flags_of(self._adm_state)
            logger.info(f"[zhutian] 诸天难度 {self._adm_difficulty}｜"
                        f"修仙管理员 {len(self._adm_state['masters'])} 人")
        except Exception as exc:      # 世界状态读失败不能挡住插件启动
            logger.warning(f"[zhutian] 超管世界状态载入失败：{exc}")
        self._reminder_task = asyncio.create_task(self._daily_reminder_loop())
        self._lingjie_task = asyncio.create_task(self._lingjie_loop())
        self._era_push_task = asyncio.create_task(self._era_push_loop())
        self._xiangu_npc_task = asyncio.create_task(self._xiangu_npc_loop())
        self._xg_auction_task = asyncio.create_task(self._xg_auction_loop())
        self._last_era_push_key = ""      # 上次广播过的时代身份键（epoch:index）
        self._last_era_push_total = -1    # 上次广播进度时的世界总年数
        logger.info("[zhutian] M0 插件已加载。")

    async def terminate(self) -> None:
        task = getattr(self, "_reminder_task", None)
        if task:
            task.cancel()
        task = getattr(self, "_lingjie_task", None)
        if task:
            task.cancel()
        task = getattr(self, "_era_push_task", None)
        if task:
            task.cancel()
        task = getattr(self, "_xiangu_npc_task", None)
        if task:
            task.cancel()
        task = getattr(self, "_xg_auction_task", None)
        if task:
            task.cancel()
        await self.db.close()
        await render.shutdown()

    async def _era_broadcast(self, text: str) -> None:
        """时代变化主动消息：向白名单群推送（对齐原版 Era.notifyGroups 广播）。"""
        if not text:
            return
        from astrbot.api.event import MessageChain
        from astrbot.api.message_components import Plain

        platform_id = "大肥鱼"  # qq_official 平台实例 id
        for gid in self.whitelist_groups:
            try:
                await self.context.send_message(
                    f"{platform_id}:GroupMessage:{gid}",
                    MessageChain(chain=[Plain(text)]),
                )
            except Exception as e:  # 单群失败不影响其它群（QQ 主动消息有额度限制）
                logger.warning(f"[zhutian] 时代推送发送失败 {gid}: {e}")

    async def _era_push_loop(self) -> None:
        """后台监听世界历法：每 60s 懒推进一次，跨时代/跨纪元或满千年即推送（W34）。

        对齐原版 EraChangeTask：每 tick（默认 2h/1000 年）发进度播报，跨时代发
        broadcastNewEra 变迁推送；玩家指令触发的懒推进也在此兜底感知。
        """
        try:
            while True:
                await asyncio.sleep(60)
                try:
                    span, step = self._era_tick_args()
                    raw = await self.db.get_era()
                    st, info = era_mod.tick(raw, time.time(),
                                            tick_seconds=span, years_per_tick=step)
                    if info["ticks"]:
                        await self.db.save_era(st)
                    key = era_mod.era_key(st)
                    changed_text = era_mod.push_text(info)
                    crossed = (key != getattr(self, "_last_era_push_key", "") and self._last_era_push_key)
                    if changed_text and (crossed or self._last_era_push_key == ""):
                        await self._era_broadcast(changed_text)
                    if key != getattr(self, "_last_era_push_key", ""):
                        self._last_era_push_key = key
                    # 每满一个 tick 年数（默认 1000 年）发一次进度播报（原版每千年通知）
                    if (self._val("ERA_PROGRESS_PUSH", 1) and info["ticks"]
                            and st["years_total"] - self._last_era_push_total >= step):
                        self._last_era_push_total = st["years_total"]
                        await self._era_broadcast(
                            era_mod.progress_text(info["new"], info["years"]))
                    if self._last_era_push_total < 0:
                        self._last_era_push_total = st["years_total"]
                except Exception as exc:
                    logger.warning(f"[zhutian] 时代推送轮询异常：{exc}")
        except asyncio.CancelledError:
            pass

    async def _xg_broadcast(self, groups: list[str], text: str) -> None:
        if not text:
            return
        from astrbot.api.event import MessageChain
        from astrbot.api.message_components import Plain

        for gid in groups:
            try:
                await self.context.send_message(
                    f"大肥鱼:GroupMessage:{gid}",
                    MessageChain(chain=[Plain(text)]),
                )
            except Exception as exc:
                logger.warning(f"[zhutian] 星阁群推送失败 {gid}: {exc}")

    async def _xg_auction_loop(self) -> None:
        """每分钟结算到期场次，并按原版晚间时段开启官方拍品。"""
        try:
            while True:
                await asyncio.sleep(60)
                try:
                    async with self.db.calamity_lock:
                        state = await self.db.get_calamity()
                        w = xg_mod.world_of(state)
                        now = time.time()
                        groups = sorted(set(
                            w["groups"] + w["groups2"] +
                            [str(g) for kind in ("official", "inner")
                             for g in ((w.get(kind) or {}).get("groups") or [])]
                        ))
                        balances: dict[str, tuple[int, int]] = {}
                        for kind in xg_mod.KINDS:
                            lot = w.get(kind)
                            if not isinstance(lot, dict):
                                continue
                            bidder = str(lot.get("bidder") or "0")
                            if bidder in ("0", "-1", "") or bidder in balances:
                                continue
                            raw = await self.db.get_player(bidder)
                            if raw:
                                bidder_doc = PlayerDoc(**raw)
                                balances[bidder] = (
                                    int(bidder_doc.stones),
                                    int(yuanshi.system_of(bidder_doc).get("amount") or 0),
                                )
                        notes, ops = xg_mod.tick(
                            w, now, self._xg_pools, random.Random(time.time_ns()),
                            balances, xg_mod.open_kinds_at(now), allow_player_open=False,
                            scheduled=True)
                        if notes or ops:
                            async with self.db.transaction():
                                for op in ops:
                                    await self._xg_op(op)
                            xg_mod.set_world(state, w)
                            await self.db.save_calamity(state)
                    if notes:
                        await self._xg_broadcast(groups, "\n".join(notes))
                except Exception as exc:
                    logger.warning(f"[zhutian] 星阁定时拍卖异常：{exc}")
        except asyncio.CancelledError:
            pass

    async def _xiangu_npc_loop(self) -> None:
        """Advance one eligible NPC action on each active private map."""
        try:
            while True:
                await asyncio.sleep(5)
                try:
                    for uid in await self.db.all_player_uids():
                        async with self._pl_lock(uid):
                            raw = await self.db.get_player(uid)
                            if not raw:
                                continue
                            doc = PlayerDoc(**raw)
                            st = xgm_mod.state_of(doc)
                            if not st.get("active") or not st.get("map"):
                                continue
                            moved = xn_mod.advance_autonomous(st, time.time() * 1000)
                            if moved:
                                await self.db.save_player(doc.model_dump())
                except Exception as exc:
                    logger.warning(f"[zhutian] 仙古 NPC 自主推进异常：{exc}")
        except asyncio.CancelledError:
            pass

    async def _daily_reminder_loop(self) -> None:
        """每日 00:05（上海时区）向白名单群推送日常刷新提醒（对齐原版 AutoDailyTask 时点）。"""
        from astrbot.api.event import MessageChain
        from astrbot.api.message_components import Plain

        platform_id = "大肥鱼"  # qq_official 平台实例 id
        try:
            while True:
                now = time.time()
                hm = time.strftime("%H:%M", time.gmtime(now + 8 * 3600))
                dkey = time.strftime("%Y-%m-%d", time.gmtime(now + 8 * 3600))
                if hm == "00:05" and getattr(self, "_last_reminder_date", "") != dkey:
                    self._last_reminder_date = dkey
                    text = (
                        "【诸天修仙 · 每日刷新】\n"
                        "#修仙签到 / #获取每日任务 已刷新，道友们今天也别忘了修行。"
                    )
                    for gid in self.whitelist_groups:
                        try:
                            await self.context.send_message(
                                f"{platform_id}:GroupMessage:{gid}",
                                MessageChain(chain=[Plain(text)]),
                            )
                        except Exception as e:  # 单群失败不影响其它群
                            logger.warning(f"[zhutian] 每日提醒发送失败 {gid}: {e}")
                await asyncio.sleep(20)
        except asyncio.CancelledError:
            pass

    # ---- 门禁 ----

    def _allowed(self, event: AstrMessageEvent) -> bool:
        if not self.whitelist_groups:
            return True
        gid = event.get_group_id()
        return not gid or str(gid) in self.whitelist_groups

    async def _find_player(self, event: AstrMessageEvent) -> PlayerDoc | None:
        raw = await self.db.get_player(event.get_sender_id())
        return PlayerDoc(**raw) if raw else None

    async def _require_player(self, event: AstrMessageEvent) -> tuple[PlayerDoc | None, str | None]:
        uid = event.get_sender_id()
        now = time.time()
        if now - self._last_cmd_ts.get(uid, 0.0) < 0.5:
            return None, "修炼节奏太快，稍缓再发。"
        self._last_cmd_ts[uid] = now
        doc = await self._find_player(event)
        if not doc:
            return None, f"道友尚未踏入仙途，请发送「{CMD_START}」。"
        if doc.ext.get("banned"):
            # W8-F1 天牢：限时封禁到期自动赦免（#封禁修仙 无 jail_until，仍是永久封禁）
            try:
                until = float(doc.ext.get("jail_until") or 0)
            except (TypeError, ValueError):
                until = 0.0
            if until and until <= now:
                doc.ext["banned"] = False
                doc.ext.pop("jail_until", None)
                await self.db.save_player(doc.model_dump())
            else:
                return None, "道友已被打入天牢，" + adm_mod.jail_left(doc, now)
        resolved = lifespan.resolve_if_due(
            doc, now, forced=bool(self._adm_flags.get("forced", True)))   # 难度「简单/普通」不强制轮回
        if resolved:
            await self.db.save_player(doc.model_dump())
            await self._drop_legacy_ring(doc, now)     # W8-A4：转世留下遗落纳戒
            await self._xg_baodi_drop(doc)             # W27：库存封入仙遗宝地
            return None, resolved
        try:                                            # W21-F1：自动任务惰性补领
            at_lines, at_items, doc = at_mod.run_if_due(
                doc, now, random.Random(f"{uid}:at:{int(now)}"),
                int(self._val("SIGN_REWARD_MIN", 100)),
                int(self._val("SIGN_REWARD_MAX", 500)),
                float(mingge.multiplier(doc, "签到奖励倍率") or 1.0),
                float((daofa.card_bonus(doc, now) or {}).get("sign", 0) or 0))
            for _atk, _atv in at_items.items():
                await self.db.add_items(doc.uid, {_atk: int(_atv)})
        except Exception:
            pass
        return doc, None

    SMART_TEXT_LIMIT = 200

    def _is_panel(self, text: str) -> bool:
        """面板判定：超字数、或行数 ≥5、或以 --- 标题行开头 → 出图。"""
        if len(text) > self.SMART_TEXT_LIMIT:
            return True
        lines = [ln for ln in text.split("\n") if ln.strip()]
        return len(lines) >= 5 or text.lstrip().startswith("---")

    async def _smart(self, event: AstrMessageEvent, text: str, title: str = "诸天修仙"):
        """智能回复：长文本/多行面板自动转通用面板图，渲染失败回退原文。"""
        if not self._is_panel(text):
            yield event.plain_result(text)
            return
        # W34 审计：按钮回调事件的图片被动回复会被 QQ 拒绝（sjm.sub 事故），
        # 交互事件一律降级为文本——所有经 _smart 的按钮路由（sp./sy./fl./dz./bm.…）自动受益。
        if event.get_button_interaction():
            yield event.plain_result(text)
            return
        if self.render_on:
            png = await render.render_panel(
                "text",
                {"title": title, "footer": "智能排版", "lines": text.split("\n")},
                self.panel_dir,
            )
            if png:
                yield event.image_result(str(png))
                return
        yield event.plain_result(text)

    def _kb_next(self, event: AstrMessageEvent, title: str, row, plain: str):
        """按钮气泡带内容：标题 + 回退指令；无组件时回退纯文本（W34 排版修复）。"""
        fb = str(getattr(row, "fallback_text", "") or "")
        text = f"{title}点击直达（或回复：{fb}）" if fb else title
        res = self._kb(event, text, row)
        if res is not None and _uk_avail():
            res.use_markdown(True)
        return res if res is not None else event.plain_result(plain)

    # ---- 指令 ----

    @filter.command(CMD_START, "踏入仙途，创建角色")
    async def handle_start(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        uid = event.get_sender_id()
        if await self.db.get_player(uid):
            yield event.plain_result("道友已踏入仙途，无需重复此举。")
            return
        doc = create_player(uid, event.get_sender_name() or "", self.content.table("Level/练气境界"))
        import random as _random
        mg = mingge.ensure(doc, self.content, _random.Random(f"{uid}:mingge"))
        await self.db.save_player(doc.model_dump())
        entry = realm_entry(doc, self.content.table("Level/练气境界"))
        fate = f"\n命格判定：【{mg.get('name')}】——{mg.get('desc', '')}" if mg else ""
        yield event.plain_result(
            f"恭喜道友 {doc.name or uid} 踏入仙途！\n"
            f"起始境界：【{entry.get('level', '凡人')}】{fate}\n"
            f"发送「{CMD_STATUS}」查看状态。"
        )

    @filter.command(CMD_STATUS, "查看修仙状态")
    async def handle_status(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc = await self._find_player(event)
        if not doc:
            yield event.plain_result(f"道友尚未踏入仙途，请发送「{CMD_START}」。")
            return
        text, data = self._status_text(doc)
        if self.render_on:
            png = await render.render_panel("status", data, self.panel_dir)
            if png:
                yield event.image_result(str(png))
                return
        yield event.plain_result(text)

    def _furn_item(self, name: str):
        """W8-C4：优先查锻造材料九维表，再回退全局物品索引。"""
        return self._furn_mats.get(str(name)) or self.item_index.get(str(name))

    def _stats(self, doc: PlayerDoc) -> equipment.Stats:
        # 本命帝兵 / 锻炉神兵都是玩家私有数据（不在全局 item_index），
        # 按玩家注入 lookup 避免跨玩家同名污染。
        w = dibing.system_of(doc)
        if w:
            card = dibing.item_card(w)
            name = card["name"]

            def lookup(n: str):
                if n == name:
                    return card
                art = dzl_mod.item_card(doc, n)
                return art if art is not None else self.item_index.get(n)
        else:
            def lookup(n: str):
                art = dzl_mod.item_card(doc, n)
                return art if art is not None else self.item_index.get(n)
        st = equipment.aggregate(
            doc, self.content.table(doc.realm_table), lookup,
            doc.ext.get("enh"), set(doc.ext.get("imperial") or []),
            physique_table=self.content.table("Level/炼体境界"),
        )
        # 魔头禁术：魔功 + 魂奴 三维加成；W8-F6 外来道果/道果裂痕/人傀出战同乘区
        ev = motou.state_of(doc)
        mult = (1.0 + motou.magic_bonus(ev) + motou.slave_bonus(ev, time.time())
                + pup_mod.battle_bonus(ev, time.time()))
        # W28：极尽升华（×4 时限）+ 天神书院择院（圣院全极境 +20%）
        mult *= ab_mod.sublime_mult(doc)
        mult *= acd_mod.combat_mult(doc)
        if abs(mult - 1.0) > 1e-9:
            st = equipment.Stats(
                atk=int(st.atk * mult), defense=int(st.defense * mult),
                hp=int(st.hp * mult), bao=st.bao, set_lines=st.set_lines,
            )
        return st

    def _cls_of(self, name: str) -> str:
        """物品类别（内景地占格按类别算）。"""
        row = self.item_index.get(str(name or ""))
        return str((row or {}).get("class") or "")

    def _hp_pair(self, doc: PlayerDoc) -> tuple[int, int]:
        """(当前气血, 上限)。ext 缺失视为满血；上限缩小时自动钳制。"""
        max_hp = self._stats(doc).hp
        cur = min(float(doc.ext.get("hp", max_hp)), float(max_hp))
        return int(max(cur, 0)), int(max_hp)

    async def _ensure_boss(self) -> dict:
        row = await self.db.get_boss()
        if row is None:
            health, reward = boss.boss_specs(1)
            await self.db.init_boss(1, health, reward)
            row = await self.db.get_boss()
        return row

    def _status_text(self, doc: PlayerDoc) -> tuple[str, dict]:
        # shortcut: 纯文本面板，M1 面板出图时接 Jinja2+Playwright，此处接口保持返回 str
        table = self.content.table(doc.realm_table)
        entry = realm_entry(doc, table)
        nxt = next_realm_entry(doc, table)
        req = entry.get("exp", 0)
        st = self._stats(doc)
        hp_cur, hp_max = self._hp_pair(doc)
        body_entry = cultivate.physique_entry(doc, self.content.table("Level/炼体境界"))
        power = (st.atk + st.defense * 1.1 + st.hp * 0.5) / 10000   # 原版战力公式
        if power >= 1e8:
            power_txt = f"{power / 1e8:.2f} 亿"
        elif power >= 1e4:
            power_txt = f"{power / 1e4:.1f} 万"
        else:
            power_txt = f"{power:.0f}"
        equips = []
        enh = doc.ext.get("enh") or {}
        for slot, name in (doc.ext.get("equipment") or {}).items():
            item = self.item_index.get(name) or {}
            parts = []
            for key, label in (("atk", "攻"), ("def", "防"), ("HP", "血"), ("bao", "暴")):
                f_, r_ = equipment._split(item.get(key))
                if f_:
                    parts.append(f"{label}+{int(f_):,}")
                elif r_:
                    parts.append(f"{label}+{r_:.0%}")
            lv = int((enh.get(slot, 0) or 0))
            equips.append({
                "slot": slot, "name": name,
                "meta": " ".join(parts) if parts else "无加成",
                "enh": f"+{lv}" if lv else "",
            })
        endSt = endless.state_of(doc)
        data = {
            "name": doc.name or doc.uid[:8] + "…",
            "uid": doc.uid,
            "realm": entry.get("level", "未知"),
            "physique": body_entry.get("level", ""),
            "title": (endless.title_of(endSt).get("name") or ""),
            "power": power_txt,
            "exp": doc.exp, "req": req,
            "next": nxt["level"] if nxt else "",
            "progress": min(100.0, doc.exp / req * 100) if req else 100.0,
            "hp_cur": hp_cur, "hp_max": hp_max,
            "xueqi": int(float(doc.ext.get("xueqi", 0) or 0)),
            "stones": doc.stones,
            "atk": st.atk, "defense": st.defense, "hp": st.hp,
            "bao": f"{st.bao:.0%}" if st.bao else "",
            "set_lines": list(st.set_lines),
            "equips": equips,
            "footer": "状态面板",
        }
        lg = doc.ext.get("linggen")
        data["linggen"] = linggen.describe(lg) if isinstance(lg, dict) else ""
        lines = [
            f"--- 道友 {data['name']} 的仙途 ---",
            f"境界：{data['realm']}｜炼体：{data['physique']}"
            + (f"｜称号：{data['title']}" if data["title"] else ""),
            f"战力：{data['power']}",
            f"修为：{data['exp']}" + (f" / {data['req']}（下一境 {data['next']}）" if nxt else "（已臻化境）"),
            f"气血：{hp_cur} / {hp_max}｜血气：{data['xueqi']:,}",
            f"灵石：{doc.stones}",
            f"攻击 {st.atk} · 防御 {st.defense} · 血量 {st.hp}"
            + (f" · 暴击 {st.bao:.0%}" if st.bao else ""),
        ]
        if data["linggen"]:
            lines.append(f"灵根：{data['linggen']}")
        if equips:
            lines.append("装备：" + "、".join(f"[{e['slot']}]{e['name']}{e['enh']}" for e in equips))
        state_note = ""
        if doc.state == "闭关中":
            cap = int(self._val("CULTIVATE_MAX_MINUTES", 7200))
            period = 30
            planned = doc.ext.get("cultivate_minutes")
            elapsed = max(0.0, (time.time() - doc.state_start) / 60)
            counted = min(elapsed, float(planned) if planned else float(cap), float(cap))
            floored = int(counted // period) * period
            gongfa_bonus = 0
            for gname in (doc.ext.get("gongfa") or []):
                g = self.item_index.get(gname) or {}
                try:
                    gongfa_bonus += float(g.get("修炼加成") or 0)
                except (TypeError, ValueError):
                    pass
            buffs = doc.ext.get("buffs") or {}
            big = buffs.get("biguan") if isinstance(buffs.get("biguan"), dict) else {}
            biguan_bonus = float(big.get("bonus", 0) or 0)
            base_per_min = int(self._val("CULTIVATE_EXP_PER_REALM", 10)) * (max(0, doc.realm_index) + 1)
            eff_rate = max(1, int(
                base_per_min * (1 + linggen.eff_of(doc) + gongfa_bonus + biguan_bonus)))
            note = f"闭关中（已 {int(elapsed)} 分钟"
            note += f"，计划 {planned} 分钟" if planned else ""
            note += f"，现在出关可得修为 {int(floored * eff_rate)}）"
            lines.append("状态：" + note)
            state_note = note
        elif doc.state == "降妖中":
            period = cultivate.WORK_PERIOD
            planned = doc.ext.get("work_minutes")
            elapsed = max(0.0, (time.time() - doc.state_start) / 60)
            counted = min(elapsed, float(planned) if planned else float(period * cultivate.WORK_CYCLES),
                          float(period * cultivate.WORK_CYCLES))
            floored = int(counted // period) * period
            note = f"降妖中（已 {int(elapsed)} 分钟"
            note += f"，计划 {planned} 分钟" if planned else ""
            note += f"，现在归来可得灵石 {int(floored * self._work_stones_per_min(doc)):,}）"
            lines.append("状态：" + note)
            state_note = note
        elif doc.state == "秘境中":
            note = f"正在【{(doc.ext.get('explore') or {}).get('place', '?')}】探索"
            lines.append("状态：" + note)
            state_note = note
        return "\n".join(lines), data

