    # 源版帮助目录（config/help/*.yaml 1:1 迁移至 data/help/*.json）
    HELP_CATALOGS = {
        "诸天": "zhutianhelp", "灵根": "linggenhelp", "职业": "zhiyehelp",
        "活动": "huodonghelp", "小世界": "xiaoshijiehelp", "师徒": "shituhelp",
        "基础": "jichuhelp", "宗门": "Association", "设置": "set",
        "星海": "xinghai", "周年": "zhounianqing", "通用": "helpcopy",
        "扩展": "help2", "世界": "help",
    }

    @filter.command(CMD_HELP, "修仙帮助")
    async def handle_help(self, event: AstrMessageEvent, catalog_name: str = ""):
        if not self._allowed(event):
            return
        key = (catalog_name or "").strip().lstrip("#")
        if key:
            fname = self.HELP_CATALOGS.get(key)
            if not fname:
                names = "、".join(self.HELP_CATALOGS)
                yield event.plain_result(f"查无帮助目录「{key}」。可用：{names}")
                return
            groups = self.content.table("help/" + fname)
            if not isinstance(groups, list) or not groups:
                yield event.plain_result("该帮助目录为空。")
                return
            if self.render_on:
                png = await render.render_panel(
                    "catalog", {"title": f"诸天修仙 · {key}帮助", "groups": groups},
                    self.panel_dir)
                if png:
                    yield event.image_result(str(png))
                    return
            lines = [f"【{key}帮助】"]
            for g in groups:
                lines.append(f"—— {g.get('group', '')} ——")
                for it in g.get("list", []):
                    lines.append(f"{it.get('title', '')}：{it.get('desc', '')}")
            async for _r in self._smart(event, "\n".join(lines)):
                yield _r
            return
        groups = self._help_groups()
        if self.render_on:
            png = await render.render_panel(
                "help", {"title": "诸天修仙 · 指令总览", "groups": groups}, self.panel_dir)
            if png:
                yield event.image_result(str(png))
                return
        lines = ["【诸天修仙 · 已开放指令】"]
        for g in groups:
            lines.append(f"—— {g['title']} ——")
            for c, d in g["lines"]:
                lines.append(f"{c}：{d}")
        async for _r in self._smart(event, "\n".join(lines)):
            yield _r
    # ---- 数值辅助 ----

    def _val(self, key: str, default):
        return (self.config.get("VALUES", {}) or {}).get(key, default)

    @filter.command(CMD_SIGN, "每日签到领灵石")
    async def handle_sign(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        import random as _random
        ok, msg, d = cultivate.sign_in(
            doc, int(self._val("SIGN_REWARD_MIN", 100)), int(self._val("SIGN_REWARD_MAX", 500)),
            time.time(), _random.Random(f"{doc.uid}:{int(time.time() // 86400)}"),
            reward_mult=mingge.multiplier(doc, "签到奖励倍率")
            * (2 if daofa.active(doc, time.time()) else 1)      # 命格（W4-2）+ 道法仙术签到翻倍
            * (1 + daofa.card_bonus(doc, time.time())["sign"]),  # 道法卡（W7-4）
        )
        if daofa.active(doc, time.time()):
            msg += "\n【道法仙术】签到奖励 ×2"
        card_tier, _card_cfg = daofa.card_of(doc, time.time())
        if card_tier:
            msg += f"\n【{card_tier}】签到灵石 +{daofa.card_bonus(doc, time.time())['sign']:.0%}"
        if ok:
            lost, dead = lifespan.daily_decay(
                d, time.time(), decay=bool(self._adm_flags.get("decay", True)))   # 寿元流逝（W2-2 / F1 难度）
            if dead:
                msg = lifespan.mark_death(d, time.time())        # W7-4：先进 24h 救援窗口
            elif lost:
                msg += f"\n岁月无声，寿元 -{lost}（剩余 {int(d.ext['shouyuan']):,}）"
            async with self.db.transaction():
                await self.db.save_player(d.model_dump())
                await self.db.add_items(doc.uid, {"秘境之匙": 1})  # 对齐原版 Sign.ticket=1/天
        yield event.plain_result(msg)

    @filter.command(CMD_TIANDAO)
    async def handle_tiandao(self, event: AstrMessageEvent):
        """天道赐福：破虚境+，每日一次（原版 UserStart.js:663-788）。"""
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        ok, msg, d, items = blessing.tiandao_gift(
            doc, time.time(), mingge.multiplier(doc, "签到奖励倍率"),
            daofa=daofa.active(doc, time.time()))
        if ok:
            async with self.db.transaction():
                await self.db.save_player(d.model_dump())
                await self.db.add_items(doc.uid, items)
        yield event.plain_result(msg)
        # W33：原版 DAILY_SIGN_BUTTONS
        res = self._kb(event, "", self._daily_sign_rows())
        if res:
            yield res

    async def _lottery_run(self, event, count: int):
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        import random as _random
        ok, msg, d, items = blessing.lottery(
            doc, count, _random.Random(f"{doc.uid}:lottery:{time.time_ns()}"),
            per_draw=2 if daofa.active(doc, time.time()) else 1)
        if ok:
            async with self.db.transaction():
                await self.db.save_player(d.model_dump())
                await self.db.add_items(doc.uid, items)
        yield event.plain_result(msg)

    @filter.command(CMD_LOTTERY)
    async def handle_lottery(self, event: AstrMessageEvent, arg: str = ""):
        """每日抽奖：#每日抽奖 次数（原版 41 项等概率）。"""
        import re as _re
        if not self._allowed(event):
            return
        m = _re.search(r"\*?(\d+)", arg or "")
        async for r in self._lottery_run(event, int(m.group(1)) if m else 1):
            yield r

    @filter.regex(r"^#每日抽奖\*(\d+)$")
    async def handle_lottery_star(self, event: AstrMessageEvent):
        """兼容原版写法 #每日抽奖*N（AstrBot 命令匹配要求空格，故单列 regex 入口）。"""
        import re as _re
        if not self._allowed(event):
            return
        m = _re.match(r"^#每日抽奖\*(\d+)$", (event.get_message_str() or "").strip())
        async for r in self._lottery_run(event, int(m.group(1)) if m else 1):
            yield r

    @filter.command(CMD_DAOFA_OPEN)
    async def handle_daofa_open(self, event: AstrMessageEvent):
        """管理员开通/续期道法仙术 30 天（原版 AdminSuper.js:596）。"""
        if not self._allowed(event):
            return
        if not event.is_admin:
            yield event.plain_result("此权柄唯管理员可执。")
            return
        target, terr = await self._target_doc(event)
        if terr:
            yield event.plain_result(terr)
            return
        dt = target.model_copy(deep=True)
        ok, msg = daofa.open_for(dt, time.time())
        if ok:
            await self.db.save_player(dt.model_dump())
        yield event.plain_result(msg)

    @filter.command(CMD_DAOFA_GIFT)
    async def handle_daofa_gift(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        ok, msg, d, items = daofa.gift(
            doc, time.time(), mingge.multiplier(doc, "签到奖励倍率"))
        if ok:
            async with self.db.transaction():
                await self.db.save_player(d.model_dump())
                await self.db.add_items(doc.uid, items)
        yield event.plain_result(msg)

