    @filter.command(CMD_OPEN, "出关结算")
    async def handle_open(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        rate = int(self._val("CULTIVATE_EXP_PER_MIN", 20))
        # 原版效率等式（player_efficiency）：加法聚合 1 + 灵根eff + 功法修炼加成 + 辟谷丹
        gongfa_bonus = 0
        for gname in (doc.ext.get("gongfa") or []):
            g = self.item_index.get(gname) or {}
            try:
                gongfa_bonus += float(g.get("修炼加成") or 0)
            except (TypeError, ValueError):
                pass
        ling_bonus = linggen.eff_of(doc)
        buffs = doc.ext.get("buffs") or {}
        big = buffs.get("biguan") if isinstance(buffs.get("biguan"), dict) else {}
        biguan_bonus = float(big.get("bonus", 0) or 0)
        # 对齐原版 biguan_jiesuan：每周期基础修为 = size(默认10) × 境界id × 效率乘区
        base_per_min = int(self._val("CULTIVATE_EXP_PER_REALM", 10)) * (max(0, doc.realm_index) + 1)
        eff_rate = max(1, int(base_per_min * (1 + ling_bonus + gongfa_bonus + biguan_bonus)))
        # 魔头禁术：魂印缠身 → 闭关效率 -30%
        brand_mult = motou.brand_penalty(motou.state_of(doc), time.time())
        if brand_mult < 1.0:
            eff_rate = max(1, int(eff_rate * brand_mult))
        ok, msg, d = cultivate.end_cultivate(
            doc, time.time(), eff_rate,
            int(self._val("CULTIVATE_MAX_MINUTES", 7200)),
        )
        if ok:
            self._wxl_track(d, "seclusion")  # 问仙令每日任务
            await self.db.save_player(d.model_dump())
        yield event.plain_result(msg)

    def _work_stones_per_min(self, doc: PlayerDoc) -> int:
        """原版 dagong_jiesuan：每分钟灵石 = work.size(15) × 境界id × 效率乘区 × 0.5。"""
        gongfa_bonus = 0
        for gname in (doc.ext.get("gongfa") or []):
            g = self.item_index.get(gname) or {}
            try:
                gongfa_bonus += float(g.get("修炼加成") or 0)
            except (TypeError, ValueError):
                pass
        buffs = doc.ext.get("buffs") or {}
        big = buffs.get("biguan") if isinstance(buffs.get("biguan"), dict) else {}
        biguan_bonus = float(big.get("bonus", 0) or 0)
        base_per_min = int(self._val("WORK_STONES_PER_REALM", 15)) * (max(0, doc.realm_index) + 1)
        return max(1, int(base_per_min * (1 + linggen.eff_of(doc) + gongfa_bonus + biguan_bonus) * 0.5))

    async def _work_run(self, event: AstrMessageEvent, planned: int | None):
        """降妖开始（原版 PlayerControl.Dagong）：封印/气血校验 + 15 分钟档定时动作。"""
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        blocked = era_mod.seal_block(doc, await self._era_state(), "降妖")
        if blocked:
            yield event.plain_result(blocked)
            return
        hp_cur, _hp_max = self._hp_pair(doc)
        if hp_cur < cultivate.WORK_MIN_HP:
            yield event.plain_result("你都伤成这样了，先去疗伤吧。")
            return
        ok, msg, d = cultivate.start_work(doc, planned)
        if ok:
            await self.db.save_player(d.model_dump())
        yield event.plain_result(msg)

    @filter.command(CMD_WORK, "降妖赚灵石")
    async def handle_work(self, event: AstrMessageEvent, minutes: str = ""):
        if not self._allowed(event):
            return
        arg = (minutes or "").strip()
        digits = "".join(ch for ch in arg if ch.isdigit())
        async for r in self._work_run(event, int(digits) if digits else None):
            yield r

    @filter.regex(r"^#降妖(\d+)分?钟?$")
    async def handle_work_attached(self, event: AstrMessageEvent):
        """兼容原版写法 #降妖30分钟（AstrBot 命令匹配要求空格，故单列 regex 入口）。"""
        import re as _re
        if not self._allowed(event):
            return
        m = _re.match(r"^#降妖(\d+)分?钟?$", (event.get_message_str() or "").strip())
        async for r in self._work_run(event, int(m.group(1)) if m else None):
            yield r

    @filter.command(CMD_WORK_END, "降妖归来结算")
    async def handle_work_end(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        # 魔头禁术：魂印缠身 → 降妖效率同步受抑（对齐出关处理）
        brand_mult = motou.brand_penalty(motou.state_of(doc), time.time())
        spm = self._work_stones_per_min(doc)
        if brand_mult < 1.0:
            spm = max(1, int(spm * brand_mult))
        ok, msg, d = cultivate.end_work(doc, time.time(), spm)
        if ok:
            await self.db.save_player(d.model_dump())
        yield event.plain_result(msg)

    # ---- 物品 / 坊市 ----

    # 稀有度 → 分组 [下界, 上界)/标签/颜色（修仙配色：凡→仙递进）
    _RARITY_TIERS = (
        (9, 99, "仙品 · 九阶以上", "#e88a8a"),
        (8, 9, "八阶 · 淬金", "#f0d78c"),
        (7, 8, "七阶 · 流紫", "#b48ce8"),
        (6, 7, "六阶 · 凝蓝", "#6fb8e8"),
        (4, 6, "四五行 · 凝碧", "#7ec97f"),
        (0, 4, "凡阶 · 一至三阶", "#9aa5b5"),
    )

    async def _bag_data(self, doc: PlayerDoc) -> dict:
        """纳戒数据（出图与文本回退同源）：按稀有度降序分组。"""
        inv = await self.db.get_inventory(doc.uid)
        rows = []
        for name, qty in inv.items():
            item = self.item_index.get(name, {})
            try:
                rar = int(float(item.get("稀有度") or 0))
            except (TypeError, ValueError):
                rar = 0
            rows.append({
                "name": name, "qty": int(qty),
                "cls": item.get("class", "?"),
                "typ": (item.get("type") or "")[:6],
                "rar": rar,
            })
        rows.sort(key=lambda r: (-r["rar"], -r["qty"], r["name"]))
        groups = []
        for lo, hi, label, color in self._RARITY_TIERS:
            picked = [r for r in rows if lo <= r["rar"] < hi]
            if picked:
                groups.append({
                    "label": label, "color": color,
                    "cells": [{k: r[k] for k in ("name", "qty", "cls", "typ")} for r in picked],
                })
        return {
            "kinds": len(rows),
            "total": sum(r["qty"] for r in rows),
            "groups": groups,
            "rows": rows,
        }

    async def _bag_text(self, doc: PlayerDoc) -> str:
        data = await self._bag_data(doc)
        if not data["rows"]:
            return "纳戒空空如也。坊市在等你：#商店"
        lines = [f"--- 道友的纳戒（共 {data['kinds']} 种 · {data['total']} 件）---"]
        for r in data["rows"][:40]:
            meta = f"{r['cls']}/{r['rar'] or '?'}阶" if r["rar"] else r["cls"]
            lines.append(f"· {r['name']} ×{r['qty']}（{meta}）")
        if len(data["rows"]) > 40:
            lines.append(f"…其余 {len(data['rows']) - 40} 种详见面板")
        return "\n".join(lines)

