    @filter.command(CMD_EQUIP, "穿戴装备")
    async def handle_equip(self, event: AstrMessageEvent, item_name: str = ""):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        name = (item_name or "").strip()
        w = dibing.system_of(doc)
        is_own_dibing = bool(w and name == w.get("name"))
        item = dibing.item_card(w) if is_own_dibing else self.item_index.get(name)
        if not item:
            yield event.plain_result(f"物品索引中找不到「{item_name}」。")
            return
        ok, msg, old = equipment.wear(doc, item)
        if not ok:
            yield event.plain_result(msg)
            return
        async with self.db.transaction():
            if not is_own_dibing:
                if not await self.db.remove_item(doc.uid, item["name"], 1):
                    raise RuntimeError("INSUFFICIENT")
            if old and not (w and old == w.get("name")):
                await self.db.add_items(doc.uid, {old: 1})
            await self.db.save_player(doc.model_dump())
        st = self._stats(doc)
        yield event.plain_result(
            f"{msg}\n当前属性：攻击 {st.atk} · 防御 {st.defense} · 血量 {st.hp}"
            + (f" · 暴击 {st.bao:.0%}" if st.bao else "")
        )

    @filter.command(CMD_UNEQUIP, "卸下装备")
    async def handle_unequip(self, event: AstrMessageEvent, slot: str = ""):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        ok, msg, old = equipment.unequip(doc, (slot or "").strip())
        if not ok:
            yield event.plain_result(msg)
            return
        w = dibing.system_of(doc)
        async with self.db.transaction():
            if not (w and old == w.get("name")):  # 本命帝兵卸下回 ext 私有档，不进纳戒
                await self.db.add_items(doc.uid, {old: 1})
            await self.db.save_player(doc.model_dump())
        yield event.plain_result(msg)

    def _equip_text(self, doc: PlayerDoc) -> str:
        cur = doc.ext.get("equipment") or {}
        st = self._stats(doc)
        lines = ["--- 已穿装备 ---"]
        if not cur:
            lines.append("（尚未穿戴任何装备，#装备 名字 进行穿戴）")
        for slot in equipment.SLOTS:
            name = cur.get(slot)
            if not name:
                lines.append(f"· {slot}：（空）")
                continue
            item = self.item_index.get(name, {})
            lines.append(
                f"· {slot}：{name}"
                f"（攻 {item.get('atk', 0)} · 防 {item.get('def', 0)} · 血 {item.get('HP', 0)}"
                + (f" · 暴击 {item.get('bao', 0):.0%}" if item.get("bao") else "")
                + "）"
            )
        lines.append(f"合计：攻击 {st.atk} · 防御 {st.defense} · 血量 {st.hp}"
                     + (f" · 暴击 {st.bao:.0%}" if st.bao else ""))
        return "\n".join(lines)

    @filter.command(CMD_MY_EQUIP, "查看已穿装备")
    async def handle_my_equip(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        yield event.plain_result(self._equip_text(doc))

    def _at_target(self, event: AstrMessageEvent) -> str | None:
        """取消息里第一个 @ 的目标（排除机器人自己）。

        QQ 官方平台只为 @ 机器人生成 At 组件；@ 群员时腾讯推送的是
        文本标记 <qqbot-at-user id="openid"/>（或 <@openid>），留在 message_str
        里，因此两条路径都要查。
        """
        import re
        comps = getattr(getattr(event, "message_obj", None), "message", None) or []
        exclude = {str(event.get_self_id() or ""), "qq_official"}
        for c in comps:
            ctype = getattr(c, "type", None) or c.__class__.__name__
            if str(ctype).lower() != "at":
                continue
            qq = str(getattr(c, "qq", "") or "")
            if qq and qq not in exclude:
                return qq
        text = event.message_str or ""
        for pat in (r'<qqbot-at-user\s+id="([^"]+)"', r"<@!?(\w+)>"):
            m = re.search(pat, text)
            if m and m.group(1) not in exclude:
                return m.group(1)
        return None

    async def _pvp_battle(self, doc: PlayerDoc, foe: PlayerDoc, now: float,
                          name_a: str, name_b: str):
        """PvP 公共战斗（W1-6 抽取）：装配 → 开场三钩 → 引擎。

        返回 (winner, log_lines, fa, fb, sa, sb)；caller 负责 CD/门槛与结算。
        """
        import random as _random
        from .core.combat.loadout import build_fighter
        from .core.combat import opening, run_1v1
        rng = _random.Random(f"{doc.uid}:{foe.uid}:{now}")
        lookup = self.item_index.get
        body_table = self.content.table("Level/炼体境界") or []
        table_a = self.content.table(doc.realm_table)
        table_b = self.content.table(foe.realm_table)

        def _base_rows(p: PlayerDoc, qi_rows: list[dict]) -> tuple[dict, dict]:
            return (qi_rows[min(int(p.realm_index), len(qi_rows) - 1)],
                    body_table[min(int(p.physique_index), len(body_table) - 1)])

        def _skill_tables():
            return {
                "atk": self.content.table("item/技能组/攻击技能") or [],
                "def": self.content.table("item/技能组/防御技能") or [],
                "heal": self.content.table("item/技能组/治疗技能") or [],
                "boost": self.content.table("item/技能组/灵根增幅技能") or [],
            }

        sa, sb = self._stats(doc), self._stats(foe)
        fa = build_fighter(doc, name_a, sa.atk, sa.defense, sa.hp, sa.bao, lookup,
                           base_rows=_base_rows(doc, table_a), skill_tables=_skill_tables())
        fb = build_fighter(foe, name_b, sb.atk, sb.defense, sb.hp, sb.bao, lookup,
                           base_rows=_base_rows(foe, table_b), skill_tables=_skill_tables())
        # 功法熟练度三乘区（combat/trigger/numeric）已在 build_fighter →
        # apply_proficiency 内统一装配（W7-0：PvE 同源，勿在此重复乘）。
        # 命格加成（W2-3）：攻击/防御/生命加成 + 暴击加成
        for f_, d_ in ((fa, doc), (fb, foe)):
            atk_b = mingge.bonus(d_, "攻击加成")
            def_b = mingge.bonus(d_, "防御加成")
            hp_b = mingge.bonus(d_, "生命加成")
            if atk_b:
                f_.atk = max(1, int(f_.atk * (1 + atk_b)))
            if def_b:
                f_.defense = max(1, int(f_.defense * (1 + def_b)))
            if hp_b:
                f_.hp_max = max(1, int(f_.hp_max * (1 + hp_b)))
                f_.hp = min(f_.hp_max, max(1, int(f_.hp * (1 + hp_b))))
            f_.bao = min(1.0, f_.bao + mingge.bonus(d_, "暴击加成"))
        opening_log: list[str] = []
        # 1) 岁云同境裁决（先于镇杀）
        opening_log += opening.suiyun_verdict(fa, fb, table_a, body_table)
        # 2) 高境镇杀
        executed = opening.high_realm_exec(fa, fb)
        if executed:
            return executed[0], opening_log + list(executed[1]), fa, fb, sa, sb
        # 3) 帝骑助战
        for atk_f, def_f, atk_doc in ((fa, fb, doc), (fb, fa, foe)):
            deck = (world_deep.decade_of(atk_doc.ext.get("zhutian") or {}) or {}).get("deck")
            msg = opening.decade_assist(atk_f, def_f, deck)
            if msg:
                opening_log.append(msg)
                if def_f.hp <= 0:
                    winner = 0 if atk_f is fa else 1
                    return winner, opening_log + [f"{def_f.name} 开场即溃，胜负已分。"], fa, fb, sa, sb
        res = run_1v1(fa, fb, rng)
        return res.winner, opening_log + list(res.log), fa, fb, sa, sb

    @filter.command(CMD_SPAR, "切磋")
    async def handle_spar(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        target_uid = self._at_target(event)
        if not target_uid:
            yield event.plain_result(f"请 @ 一位道友再发起{CMD_SPAR}。")
            return
        if target_uid == doc.uid:
            yield event.plain_result("道友岂能与自己过招？")
            return
        now = time.time()
        cd = int(self._val("SPAR_COOLDOWN_SECONDS", 60))
        last = float(doc.ext.get("spar_ts") or 0)
        if now - last < cd:
            yield event.plain_result(f"意犹未尽，气血未复，{int(cd - (now - last))} 秒后再战。")
            return
        raw = await self.db.get_player(target_uid)
        if not raw:
            yield event.plain_result("对方尚未踏入仙途，无法切磋。")
            return
        foe = PlayerDoc(**raw)

        table_a = self.content.table(doc.realm_table)
        table_b = self.content.table(foe.realm_table)
        sa, sb = self._stats(doc), self._stats(foe)
        name_a = doc.name or doc.uid[:8] + "…"
        name_b = foe.name or foe.uid[:8] + "…"

        import random as _random
        from .core.combat.loadout import build_fighter
        from .core.combat import opening, run_1v1
        rng = _random.Random(f"{doc.uid}:{foe.uid}:{now}")
        lookup = self.item_index.get
        body_table = self.content.table("Level/炼体境界") or []

        def _base_rows(p: PlayerDoc, qi_rows: list[dict]) -> tuple[dict, dict]:
            return (qi_rows[min(int(p.realm_index), len(qi_rows) - 1)],
                    body_table[min(int(p.physique_index), len(body_table) - 1)])

        def _skill_tables():
            return {
                "atk": self.content.table("item/技能组/攻击技能") or [],
                "def": self.content.table("item/技能组/防御技能") or [],
                "heal": self.content.table("item/技能组/治疗技能") or [],
                "boost": self.content.table("item/技能组/灵根增幅技能") or [],
            }

        winner, log, fa, fb, sa, sb = await self._pvp_battle(doc, foe, now, name_a, name_b)
        # 面板头部展示开场乘区后的实际数值
        sa = equipment.Stats(atk=fa.atk, defense=fa.defense, hp=fa.hp_max, bao=sa.bao,
                             set_lines=sa.set_lines)
        sb = equipment.Stats(atk=fb.atk, defense=fb.defense, hp=fb.hp_max, bao=sb.bao,
                             set_lines=sb.set_lines)
        doc.ext["spar_ts"] = now
        await self.db.save_player(doc.model_dump())

        result = (
            f"切磋结果：{name_a} 胜！" if winner == 0
            else f"切磋结果：{name_b} 胜！" if winner == 1
            else "切磋结果：势均力敌，平局！"
        )
        shown = log[:8] + [f"…（共 {len(log)} 回合）"] if len(log) > 9 else log
        if self.render_on:
            battle_data = {
                "title": "切磋", "sub": "友切无伤", "footer": "诸天修仙",
                "side_a": {"name": name_a, "atk": sa.atk, "defense": sa.defense, "hp": sa.hp},
                "side_b": {"name": name_b, "atk": sb.atk, "defense": sb.defense, "hp": sb.hp},
                "log": shown, "result": result, "extras": [],
            }
            png = await render.render_panel("battle", battle_data, self.panel_dir)
            if png:
                yield event.image_result(str(png))
                return
        yield event.plain_result(
            f"【{name_a}】攻 {sa.atk} · 防 {sa.defense} · 血 {sa.hp}"
            f"  VS  【{name_b}】攻 {sb.atk} · 防 {sb.defense} · 血 {sb.hp}\n"
            + "\n".join(shown) + "\n" + result
        )

    # ---- W1-6：打劫 / 比武 ----

    async def _pvp_target(self, event: AstrMessageEvent) -> tuple[PlayerDoc | None, str | None]:
        """解析 @ 目标并取存档。"""
        target_uid = self._at_target(event)
        if not target_uid:
            return None, f"请 @ 一位道友再动手。"
        raw = await self.db.get_player(target_uid)
        if not raw:
            return None, "对方尚未踏入仙途，不可对凡人出手。"
        return PlayerDoc(**raw), None

    def _apply_delta(self, d: PlayerDoc, delta: dict) -> None:
        if delta.get("stones"):
            d.stones = max(0, int(d.stones) + int(delta["stones"]))
        if delta.get("xueqi"):
            d.ext["xueqi"] = max(0.0, float(d.ext.get("xueqi", 0) or 0) + float(delta["xueqi"]))
        if delta.get("modao"):
            mo = d.ext.setdefault("motou", {})
            mo["modao"] = int(mo.get("modao", 0) or 0) + int(delta["modao"])

    async def _finish_pvp(self, event, doc: PlayerDoc, foe: PlayerDoc, da: dict, db: dict,
                          fa, fb, title: str, pre_log: list[str]):
        """PvP 收尾：血量回写、增量落库、出图战报。"""
        d1 = doc.model_copy(deep=True)
        d2 = foe.model_copy(deep=True)
        d1.ext["hp"] = max(0, int(fa.hp))
        d2.ext["hp"] = max(0, int(fb.hp))
        self._apply_delta(d1, da)
        self._apply_delta(d2, db)
        trib.add_insight(d1)     # 功法感悟：战斗每场 +2
        trib.add_insight(d2)
        async with self.db.transaction():
            await self.db.save_player(d1.model_dump())
            await self.db.save_player(d2.model_dump())
        return d1, d2

    @filter.command(CMD_ROB, "打劫")
    async def handle_rob(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        foe, terr = await self._pvp_target(event)
        if terr:
            yield event.plain_result(terr)
            return
        if foe.uid == doc.uid:
            yield event.plain_result("咋的，自己弄自己啊？")
            return
        now = time.time()
        b_busy = bool(foe.state) and foe.state != "空闲"
        inv_a = await self.db.get_inventory(doc.uid)
        msg = pvp.rob_check(doc, foe, now, b_busy=b_busy)
        if msg == "__NEED_STEALTH__":
            if int(inv_a.get("隐身水", 0) or 0) <= 0:
                yield event.plain_result(
                    f"{foe.name} 正在「{foe.state}」中，需要道具【隐身水】才能强行开战。"
                )
                return
            await self.db.remove_item(doc.uid, "隐身水", 1)
            pre_log = [f"{doc.name} 使用【隐身水】悄然接近正在「{foe.state}」的 {foe.name}，但被发现。"]
        elif msg:
            yield event.plain_result(msg)
            return
        else:
            pre_log = [f"{doc.name} 向 {foe.name} 发起了打劫。"]
        winner, log, fa, fb, _sa, _sb = await self._pvp_battle(doc, foe, now,
                                                               str(doc.name or "劫匪"),
                                                               str(foe.name or "苦主"))
        inv_b = await self.db.get_inventory(foe.uid)
        text, da, db = pvp.rob_settle(doc, foe, winner if winner is not None else 1,
                                      b_has_dummy=int(inv_b.get("替身人偶", 0) or 0) > 0)
        if db.pop("dummy", None):
            await self.db.remove_item(foe.uid, "替身人偶", 1)
        d1, d2 = await self._finish_pvp(event, doc, foe, da, db, fa, fb, "打劫", pre_log)
        d1.ext["rob_ts"] = now
        await self.db.save_player(d1.model_dump())
        shown = log[:8] + [f"…（共 {len(log)} 条）"] if len(log) > 10 else log
        text = "\n".join(pre_log + shown + ["", text])
        async for r in self._smart(event, text, "打劫"):
            yield r

    @filter.command(CMD_BIWU, "比武")
    async def handle_biwu(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        foe, terr = await self._pvp_target(event)
