    # ---- W8-F1 超级管理员（原版 AdminSuper 24 + GlobalInit 6，可移植 29 条） ----

    def _adm_ok(self, event: AstrMessageEvent) -> bool:
        """机器人管理员恒有权柄；修仙管理员名单由 `#设置修仙管理员` 追加。"""
        return adm_mod.is_master(
            str(event.get_sender_id()), bool(event.is_admin), self._adm_state)

    async def _adm_save(self) -> None:
        """落库世界状态，并同步内存缓存（难度开关是热路径，不能每条指令去读库）。"""
        cal = await self.db.get_calamity()
        cal["admin"] = self._adm_state
        await self.db.save_calamity(cal)
        self._adm_difficulty = adm_mod.difficulty_of(self._adm_state)
        self._adm_flags = adm_mod.flags_of(self._adm_state)

    async def _adm_note(self, event: AstrMessageEvent, text: str) -> None:
        adm_mod.log_append(self._adm_state, str(event.get_sender_id()), text)
        await self._adm_save()

    def _adm_deny(self) -> str:
        return "此权柄唯管理员可执。"

    @filter.command(CMD_AD_IMPORT_LEGACY, "预检原版玩家与纳戒 JSON 存档")
    async def handle_ad_import_legacy(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        if not event.is_admin:
            yield event.plain_result("原版存档导入仅限机器人管理员。")
            return
        source = str(self.config.get("LEGACY_IMPORT_DIR", "") or "").strip()
        if not source:
            yield event.plain_result("请先在插件配置 LEGACY_IMPORT_DIR 填写原版 resources/data 目录。")
            return
        report = legacy_mod.preflight(Path(source).expanduser())
        self._legacy_import_report = report if report.get("ready") else None
        lines = ["--- 原版存档预检 ---", f"目录：{report['source']}",
                 f"玩家：{len(report['players'])} 人｜文件哈希：{len(report['source_sha256'])} 个"]
        lines.extend(f"错误：{x}" for x in report["errors"][:8])
        lines.extend(f"提示：{x}" for x in report["warnings"][:8])
        if report.get("ready"):
            lines.append(f"预检通过。默认跳过已有角色；核对并备份后，发送「{CMD_AD_IMPORT_LEGACY_OK}」导入。")
        else:
            lines.append("预检未通过，未导入任何数据。")
        yield event.plain_result("\n".join(lines))

    @filter.command(CMD_AD_IMPORT_LEGACY_OK, "确认导入预检通过的原版存档")
    async def handle_ad_import_legacy_ok(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        if not event.is_admin:
            yield event.plain_result("原版存档导入仅限机器人管理员。")
            return
        report = self._legacy_import_report
        if not report or not report.get("ready"):
            yield event.plain_result(f"没有待确认的预检结果，请先发送「{CMD_AD_IMPORT_LEGACY}」。")
            return
        try:
            # 确认前重新扫描，避免预检后源文件变化仍导入旧快照。
            fresh = legacy_mod.preflight(report["source"])
            if fresh.get("source_sha256") != report.get("source_sha256") or not fresh.get("ready"):
                self._legacy_import_report = None
                yield event.plain_result("原版存档自预检后发生变化或校验失败；请重新预检。")
                return
            result = await legacy_mod.import_report(self.db, fresh)
        except Exception as exc:
            logger.exception(f"[zhutian] 原版存档导入失败：{exc}")
            yield event.plain_result(f"导入失败，事务已回滚：{exc}")
            return
        self._legacy_import_report = None
        await self._adm_note(event, f"原版存档导入：新增 {result['imported']} 人，跳过 {result['skipped']} 人")
        yield event.plain_result(f"导入完成：新增 {result['imported']} 人，跳过已存在 {result['skipped']} 人。原版文件未修改。")

    @staticmethod
    def _adm_tail(event: AstrMessageEvent) -> str:
        """取指令名之后的文本，并剔除 @ 标记。

        QQ 官方 @ 群员发的是文本标记 `<qqbot-at-user id="openid"/>`，会占掉
        `filter.command` 的一个参数位；带 @ 的指令若声明 int 参数会直接抛
        类型错误，故一律用本方法自己从原文里取数字/关键词。
        """
        import re
        text = str(event.message_str or "")
        text = re.sub(r'<qqbot-at-user\s+id="[^"]*"\s*/?>', " ", text)
        text = re.sub(r"<@!?\w+>", " ", text)
        parts = text.split(None, 1)
        return (parts[1] if len(parts) > 1 else "").strip()

    @classmethod
    def _adm_num(cls, event: AstrMessageEvent, default: int = 0) -> int:
        import re
        m = re.search(r"-?\d+", cls._adm_tail(event))
        return int(m.group()) if m else default

    @filter.command(CMD_AD_RELIEVE, "解除进行中的行动（原版语义，非解封封禁）")
    async def handle_ad_relieve(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        if not self._adm_ok(event):
            yield event.plain_result(self._adm_deny())
            return
        target, terr = await self._target_doc(event)
        if terr:
            yield event.plain_result(terr)
            return
        ok, msg = adm_mod.relieve_action(target, time.time())
        if not ok:
            yield event.plain_result(msg)
            return
        await self.db.save_player(target.model_dump())
        await self._adm_note(event, f"解封 {target.name}（{msg}）")
        yield event.plain_result(f"{target.name}：{msg}")

