        cost = int(s["price"] * 0.3)
        if doc.stones < cost:
            yield event.plain_result(f"打探消息需要 {cost:,} 灵石，家底不足。")
            return
        d = doc.model_copy(deep=True)
        d.stones -= cost
        await self.db.save_player(d.model_dump())
        loot = s.get("one") or []
        preview = "、".join(f"{x['name']}×{x.get('数量', 1)}" for x in loot[:5])
