    @filter.command(CMD_ANCIENT, "彼岸古文明")
    async def handle_ancient(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
