    @filter.command(CMD_ANCIENT_PUSH, "推进古文明事件")
    async def handle_ancient_push(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        state = ancient.ensure(await self.db.get_ancient())
        arg = self._calamity_arg(event.message_str, CMD_ANCIENT_PUSH)
        entry = ancient.resolve_chapter(arg) if arg else ancient.active_chapter(state)
        if not entry:
            yield event.plain_result(
                "没有可推进的章节。用法：#推进古文明事件 序号" if not arg
                else f"找不到章节「{arg}」。用 #彼岸古文明 查看四章。"
            )
            return
        now = time.time()
        last = float(doc.ext.get("ancient_cd") or 0)
        if now - last < ancient.CONTRIBUTE_CD_SECONDS:
            left = int(ancient.CONTRIBUTE_CD_SECONDS - (now - last))
            yield event.plain_result(f"刚从前线退下，调息中（还需 {left // 60 + 1} 分钟）。")
            return
        stats = self._stats(doc)
        rng = random.Random()
        result = ancient.fight_chapter(entry, stats, rng)
        hp_cur = max(1, int(result["hp_left"]))
        doc.ext["hp"] = hp_cur
        doc.ext["ancient_cd"] = now
        if not result["won"]:
            async with self.db.transaction():
                await self.db.save_player(doc.model_dump())
            yield event.plain_result(
                f"{result['log']}\n\n敌群未破，你退回营地（气血 {hp_cur}）。"
            )
            return
        amount = ancient.contribution_amount(entry, result["wins"], doc.realm_index)
        applied = ancient.contribute(state, entry, doc.uid, doc.name, amount, int(now))
        if not applied.get("ok"):
            async with self.db.transaction():
                await self.db.save_player(doc.model_dump())
            yield event.plain_result(applied.get("reason") or "未能推进。")
            return
        async with self.db.transaction():
            await self.db.save_player(doc.model_dump())
            await self.db.save_ancient(state)
        lines = [
            result["log"],
            "",
            ancient.brief_text(entry, applied),
            f"你个人累计贡献 {applied['playerContribution']}，气血 {hp_cur}。",
        ]
        if applied["chapterCompleted"]:
            lines.append(f"「{entry['name']}」就此通关！贡献过本章者可 {CMD_ANCIENT_CLAIM} {entry['order']}。")
            if applied["chainCompleted"]:
                lines.append("四章皆尽 —— 逻辑彼岸的观测链断了。")
            elif applied.get("nextEventId"):
                nxt = ancient.BY_ID.get(applied["nextEventId"])
                if nxt:
                    lines.append(f"下一章解锁：{nxt['name']}（{nxt['coordinate']}）。")
        async for r in self._smart(event, "\n".join(lines), f"古文明·{entry['name']}"):
            yield r

    @filter.command(CMD_ANCIENT_CLAIM, "领取古文明奖励")
    async def handle_ancient_claim(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        arg = self._calamity_arg(event.message_str, CMD_ANCIENT_CLAIM)
        entry = ancient.resolve_chapter(arg) if arg else None
        if not entry:
            yield event.plain_result("请指明章节。用法：#领取古文明奖励 序号（见 #彼岸古文明）")
            return
        state = ancient.ensure(await self.db.get_ancient())
        result = ancient.claim(state, entry, doc.uid, int(time.time()))
        if not result.get("ok"):
            yield event.plain_result(result.get("reason") or "无法领取。")
            return
        items = {name: qty for name, qty in result["items"]}
        doc.stones = int(doc.stones) + int(result["stones"])
        doc.exp = int(doc.exp) + int(result["exp"])
        async with self.db.transaction():
            await self.db.add_items(doc.uid, items)
            await self.db.save_player(doc.model_dump())
            await self.db.save_ancient(state)
        lines = [f"【{entry['name']}】古文明奖励已入手（贡献 {result['contribution']}）："]
        lines.extend(f"· {name} ×{qty}" for name, qty in result["items"])
        lines.append(f"· 灵石 ×{result['stones']}")
        lines.append(f"· 修为 +{result['exp']}")
        yield event.plain_result("\n".join(lines))

    @filter.command(CMD_HEAL, "灵石疗伤")
    async def handle_heal(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        hp_cur, hp_max = self._hp_pair(doc)
        if hp_cur >= hp_max:
            yield event.plain_result("气血正满，无需疗伤。")
            return
        cost = max(100, int(-(-(hp_max - hp_cur) // 1000)))  # 缺失×0.001 向上取整，最少 100
        if doc.stones < cost:
            yield event.plain_result(
                f"灵石不足：疗伤需 {cost}，道友只有 {doc.stones}。"
            )
            return
        d = doc.model_copy(deep=True, update={"stones": doc.stones - cost})
        d.ext["hp"] = hp_max
        await self.db.save_player(d.model_dump())
        yield event.plain_result(
            f"花费 {cost} 灵石疗伤，气血尽复：{hp_max} / {hp_max}。"
        )

    # ---- 秘境 ----

    def _session(self, doc: PlayerDoc) -> secret.Session | None:
        raw = doc.ext.get("explore")
        if not raw:
            return None
        fields = secret.Session.__dataclass_fields__
        return secret.Session(**{k: v for k, v in raw.items() if k in fields})

    async def _settle_explore(self, doc: PlayerDoc, sess: secret.Session, reason: str) -> str:
        """发放探索收益并清会话（事务：灵石 + 物品 + 状态复位）。"""
        d = doc.model_copy(deep=True)
        # W8-C2：盘古幡 / 炼妖壶 / 山河社稷图的收益被动在秘境结算兑现（取 max 不叠乘）
        xt_mult = max(xt_mod.yield_mult(d, k) for k in ("dungeon", "raid", "smallworld", "treasure"))
        stones_out = int(sess.stones * xt_mult)
        d.stones += stones_out
        d.state = "空闲"
        d.state_start = 0.0
        d.ext.pop("explore", None)
        if any(k in str(reason) for k in ("血战", "战败", "不敌", "陨", "亡")):
            # W8-B6：秘境道则/帝威反噬累积道伤（全身而退、传送脱身不计）
            dz_mod.add_wounds(d, 1.0, "秘境道则反噬")
        dungeon_note = ""
        if sess.dungeon:
            found = dungeon.find(sess.dungeon, self.content.table)
            if found:
                exp_g, shou_g = dungeon.rewards_of(found[0], sess.floor)
                if exp_g:
                    d.exp += exp_g
                if shou_g:
                    lifespan.grant(d, shou_g)
                if exp_g or shou_g:
                    dungeon_note = (f"副本额外：修为 +{exp_g:,}"
                                    + (f"｜寿元 +{shou_g:,}" if shou_g else ""))
        fund_note = ""
        items_out = dict(sess.items)
        mem_mult = int(mem_mod.effects(doc)["item_mult"]) if mem_mod.stage_of(doc) > 0 else 1
        sy_mult = suiyun_mod.loot_mult(doc)          # W8-B4 岁云物品倍率 1~10
        loot_mult = max(mem_mult, sy_mult)           # 两轨取 max，不叠乘（避免 40 倍通胀）
        if loot_mult > 1 and items_out:
            items_out = {k: v * loot_mult for k, v in items_out.items()}
        # W8-B1b：大荒峡谷口径投放至尊骨 / 重瞳本源 / 仙王残魂 / 世界石（不乘倍率，避免通胀）
        sp_drop = sp_mod.explore_drop(d, random.Random())
        if sp_drop:
            for _k, _v in sp_drop.items():
                items_out[_k] = int(items_out.get(_k, 0) or 0) + int(_v)
        # W8-C1：本命材料 12% 随机投放 1 件（原版无任何发放点，不补则整套系统不可玩）
        bm_drop = bm_mod.roll_drop(random.Random())
        if bm_drop:
            items_out[bm_drop] = int(items_out.get(bm_drop, 0) or 0) + 1
        # W8-C2：先天道痕 12% 投放（原版 22 件本体只靠 24h 全服择主事件，本移植补通道）
        xt_drop = xt_mod.roll_drop(random.Random())
        if xt_drop:
            for _k, _v in xt_drop.items():
                items_out[_k] = int(items_out.get(_k, 0) or 0) + int(_v)
        # W8-C3：文明薪火燃料 12% 成批投放（原版四种燃料无发放点，本移植补通道）
        dt_drop = dt_mod.roll_drop(random.Random())
        if dt_drop:
            for _k, _v in dt_drop.items():
                items_out[_k] = int(items_out.get(_k, 0) or 0) + int(_v)
        async with self.db.transaction():
            await self.db.save_player(d.model_dump())
            if items_out:
                await self.db.add_items(doc.uid, items_out)
            if sess.sect_name and sess.boss_kills:
                sdoc = await self.db.get_sect(sess.sect_name)
                if sdoc:
                    bonus = 5000 * sess.boss_kills
                    await self.db.update_sect(sess.sect_name, sdoc["level"], sdoc["fund"] + bonus)
                    fund_note = f"\n宗门基金 +{bonus}（守关 Boss ×{sess.boss_kills}），现 {sdoc['fund'] + bonus}"
        if xt_mult > 1:
            dungeon_note = (dungeon_note + "\n" if dungeon_note else "") + \
                f"【先天至宝】灵石 ×{xt_mult:.1f}（执掌被动）"
        lines = [
            f"【秘境结算 · {sess.place}】（{reason}，共探 {sess.floor} 层）",
            f"灵石 +{stones_out}",
        ]
        if items_out:
            lines.append("物品：" + "、".join(f"{n}×{q}" for n, q in items_out.items()))
            if mem_mult > 1:
                lines.append(f"【记忆命途】物品 ×{mem_mult}（每 6 个泰坦 +1 倍）")
            if sp_drop:
                lines.append("【大荒遗泽】" + "、".join(f"{n}×{q}" for n, q in sp_drop.items())
                             + "（#至尊传承 / #重瞳开天 / #孕育仙骨）")
            if bm_drop:
                lines.append(f"【本命遗珍】{bm_drop}×1（秘境偶得的炼器材料）")
            if xt_drop:
                lines.append(f"【先天道痕】{'、'.join(f'{k}×{v}' for k, v in xt_drop.items())}"
                             + "（#至宝择主 争夺先天至宝）")
            if dt_drop:
                lines.append(f"【文明薪火】{'、'.join(f'{k}×{v}' for k, v in dt_drop.items())}"
                             + "（#献祭文明 投入大道炉）")
        else:
            lines.append("物品：无")
        if dungeon_note:
            lines.append(dungeon_note)
        if fund_note:
            lines.append(fund_note.strip())
        return "\n".join(lines)

    @filter.command(CMD_SECRET, "秘境列表")
    async def handle_secret(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        table_now = self.content.table(doc.realm_table)
        places_rows = []
        for name, (gate, _f, desc) in secret.PLACES.items():
            places_rows.append({
                "name": name, "open": doc.realm_index >= gate, "desc": desc,
                "gate_name": table_now[min(gate, len(table_now) - 1)]["level"],
            })
        sess = self._session(doc)
        session_note = (
            f"你正在【{sess.place}】第 {sess.floor} 层 · #寻宝 继续 · #逃离 撤离" if sess else ""
        )
        if self.render_on:
            secret_data = {
                "title": "秘境名录", "footer": "诸天修仙",
                "places": places_rows, "session_note": session_note,
            }
            png = await render.render_panel("secret", secret_data, self.panel_dir)
            if png:
                yield event.image_result(str(png))
                return
        lines = ["--- 秘境名录 ---"]
        for name, (gate, _f, desc) in secret.PLACES.items():
            mark = "✅" if doc.realm_index >= gate else f"🔒需{table_now[min(gate, len(table_now)-1)]['level']}"
            lines.append(f"· {name}（{mark}）：{desc}")
        if sess:
            lines.append(f"※ 你正在【{sess.place}】第 {sess.floor} 层，发「{CMD_SEARCH}」继续寻宝，「{CMD_FLEE}」撤离。")
        async for _r in self._smart(event, "\n".join(lines)):
            yield _r
    @filter.command(CMD_ENTER, "降临秘境")
    async def handle_enter(self, event: AstrMessageEvent, place: str = ""):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        if self._session(doc):
            yield event.plain_result("道友已在秘境之中，何来再降临之说？")
            return
        if doc.state != "空闲":
            yield event.plain_result(f"道友正在「{doc.state}」中，无法分心。")
            return
        name = (place or "").strip()
        drow: dict = {}
        kind = ""
        fee = 0
        if name in secret.PLACES:
            gate = secret.PLACES[name][0]
            desc = secret.PLACES[name][2]
        else:
            found = dungeon.find(name, self.content.table)
            if not found:
                yield event.plain_result(
                    f"格式：{CMD_ENTER} 名字（可选：{' / '.join(secret.PLACES)}；"
                    f"或 #禁地 / #仙境 / #下界八域 / #九天十地 里的地名）")
                return
            drow, kind = found
            gate = dungeon.gate_of(drow.get("Price", 0))
            fee = 0 if suiyun_mod.free_entry(doc) else dungeon.fee_of(drow.get("Price", 0))
            desc = (f"{drow.get('Grade') or kind}｜门票 {fee:,} 灵石｜"
                    f"掉落 {len(dungeon.pool_of(drow))} 种")
        if doc.realm_index < gate:
            table = self.content.table(doc.realm_table)
            need = table[min(gate, len(table) - 1)]["level"]
            yield event.plain_result(f"【{name}】凶险异常，需修为达到【{need}】方可降临。")
            return
        hp_cur, hp_max = self._hp_pair(doc)
        if hp_cur <= hp_max * 0.3:
            yield event.plain_result("气血太虚，先疗伤再进秘境。")
            return
        if fee and int(doc.stones) < fee:
            yield event.plain_result(f"进入【{name}】需门票 {fee:,} 灵石（当前 {int(doc.stones):,}）。")
            return
        d = doc.model_copy(deep=True)
        d.state = "秘境中"
        if fee:
            d.stones -= fee
        sess = secret.Session(place=name,
                              factor=dungeon.factor_of(drow.get("Price", 0)) if drow else 0.0,
                              dungeon=name if drow else "")
        d.ext["explore"] = {"place": sess.place, "floor": 0, "stones": 0, "items": {}, "log": [],
                            "factor": sess.factor, "dungeon": sess.dungeon}
        await self.db.save_player(d.model_dump())
        yield event.plain_result(
            f"道友降临【{name}】。{desc}\n"
            f"发「{CMD_SEARCH}」寻宝，发「{CMD_FLEE}」携带收获撤离。"
        )

    @filter.command(CMD_SEARCH, "秘境寻宝")
    async def handle_search(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        sess = self._session(doc)
        if not sess:
            yield event.plain_result(f"道友不在秘境之中。先「{CMD_ENTER} 名字」降临。")
            return
        blocked = era_mod.seal_block(doc, await self._era_state(), "秘境寻宝")
        if blocked:
            yield event.plain_result(blocked)
            return
        hp_cur, hp_max = self._hp_pair(doc)
        if hp_cur <= hp_max * 0.1:
            yield event.plain_result("气血将尽，强寻恐有性命之忧。发「{0}」撤离或先「{1}」".format(CMD_FLEE, CMD_HEAL))
            return
        import random as _random
        rng = _random.Random(f"{doc.uid}:{sess.floor}:{time.time()}")
        st = self._stats(doc)
        table = self.content.table(doc.realm_table)
        entry = realm_entry(doc, table)
        base = (st.atk, st.defense, st.hp)
        # 黑皇阵纹：只在真正进入战斗时催动（逐场消耗）
        s = story_npc.state_of(doc)
        used_arrays: list[str] = []

        def _buff():
            mods, used = story_npc.battle_mods(s)
            used_arrays.extend(used)
            return mods

        me = battle.Unit(doc.name or doc.uid[:8] + "…", st.atk, st.defense, hp_cur, st.bao)
        # W4-1：秘境 PvE 接技能池/灵根法球/复活技/熟练度/命格（与 PvP 同源装填）
        from .core.combat.loadout import build_fighter as _build_fighter
        me_fighter = _build_fighter(
            doc, me.name, st.atk, st.defense, hp_cur, st.bao, self.item_index.get,
            skill_tables={
                "atk": self.content.table("item/技能组/攻击技能") or [],
                "def": self.content.table("item/技能组/防御技能") or [],
                "heal": self.content.table("item/技能组/治疗技能") or [],
                "boost": self.content.table("item/技能组/灵根增幅技能") or [],
            },
        )
        me_fighter.hp = hp_cur   # 战斗从当前气血打起

        def _protect(place: str, floor: int, enemy: str):
            got = story_npc.try_protect(s, time.time())
            if got:
                return got
            esc = story_npc.consume_escape(s)
            if esc:
                return esc, (f"【{esc}】阵纹骤然亮起，虚空裂开一道门。\n"
                              f"你在{enemy}的攻势落下前被挪出秘境，收获未失，气血尽复。")
            return None

        pool = self.drop_pool
        if sess.dungeon:
            found = dungeon.find(sess.dungeon, self.content.table)
            if found:
                pool = dungeon.pool_of(found[0]) or pool
        sess, me, flavor, fled = secret.explore(
            sess, base, me, pool, rng, sect_mode=bool(sess.sect_name), me_fighter=me_fighter,
            treasure_bonus=mingge.bonus(doc, "寻宝加成"),
            buff=_buff, protect=_protect,
            loot_rates=era_mod.seal_rates(await self._era_state()),
            loot_bonus=int(daofa.card_bonus(doc, time.time()).get("loot", 0) or 0),
        )
        if used_arrays:
            flavor = "【阵法·" + "、".join(used_arrays) + "】阵纹复苏，笼罩战场！\n" + flavor
        d = doc.model_copy(deep=True)
        d.ext["hp"] = me.hp
        d.ext["story"] = s
        d.ext["explore"] = {
            "place": sess.place, "floor": sess.floor, "stones": sess.stones,
            "items": sess.items, "log": sess.log[-30:], "factor": sess.factor,
            "sect_name": sess.sect_name, "boss_kills": sess.boss_kills,
        }
        if not sess.sect_name:  # 每日任务 3：秘境探索计数（宗门秘境不计，对齐原版"沉迷不计入"）
            await self.db.add_daily_secret(doc.uid)
        # 剧情人物邂逅（战败/传送脱身不触发）
        enc = None if fled else story_npc.meet(s, sess.place, sess.floor, time.time(), rng)
        drop_items: dict[str, int] = {}
        if enc:
            flavor = flavor + "\n" + str(enc.get("text") or "")
            if enc.get("exp_pct"):
                gain = int(d.exp * float(enc["exp_pct"]))
                d.exp += gain
                flavor += f"\n修为 +{gain:,}"
            if enc.get("item"):
                drop_items[str(enc["item"])] = 1
                flavor += f"\n（获得【{enc['item']}】×1）"
        if fled:
            if "传送阵" in flavor:
                reason = "传送脱身"
            elif "护道之约" in flavor:
                reason = "护道脱险"
            else:
                reason = "血战脱身"
            d.state = "空闲"
            text = await self._settle_explore(d, sess, reason=reason)
            if drop_items:
                await self.db.add_items(doc.uid, drop_items)
            yield event.plain_result(f"{flavor}\n{text}")
            return
        d.state = "秘境中"
        grown = bloodline.grind(d)          # W8-B1a：每次成功寻宝打磨一处秘境
        mem_mod.add_sim(d)                   # W8-B5：真实秘境结算 +2% 模拟值
        if drop_items:
            async with self.db.transaction():
                await self.db.save_player(d.model_dump())
                await self.db.add_items(doc.uid, drop_items)
        else:
            await self.db.save_player(d.model_dump())
        tail_grow = (f"\n（{grown}秘境 +{bloodline.GRIND_PER_RUN}%，#我的血脉 查看）"
                     if grown else "")
        yield event.plain_result(
            f"{flavor}\n第 {sess.floor} 层 · 本次已获 {sess.stones} 灵石 · 气血 {me.hp}/{st.hp}"
            f"{tail_grow}"
        )

    @filter.command(CMD_FLEE, "秘境撤离")
    async def handle_flee(self, event: AstrMessageEvent):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        sess = self._session(doc)
        if not sess:
            yield event.plain_result("道友不在秘境之中。")
            return
        text = await self._settle_explore(doc, sess, reason="全身而退")
        yield event.plain_result(text)

    # ---- 宗门 / 天地榜 ----

    async def _sect_members(self, name: str) -> list[tuple[str, str]]:
        """宗门成员：uid → (名字)。文档全扫（群服规模可接受）。"""
        members = []
        for p in await self.db.all_players():
            if (p.get("ext") or {}).get("sect") == name:
                members.append((p["uid"], p.get("name") or p["uid"][:8] + "…"))
        return members

    @filter.command(CMD_SECT_CREATE, "创建宗门")
    async def handle_sect_create(self, event: AstrMessageEvent, name: str = ""):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        name = (name or "").strip()
        if not name or len(name) > 12:
            yield event.plain_result(f"格式：{CMD_SECT_CREATE} 名字（12 字以内）")
            return
        ok, msg = sect.can_create(doc)
        if not ok:
            yield event.plain_result(msg)
            return
        if await self.db.get_sect(name):
            yield event.plain_result(f"「{name}」之名已被占，请另起宗号。")
            return
        d = doc.model_copy(deep=True, update={"stones": doc.stones - sect.CREATE_COST})
        d.ext["sect"] = name
        async with self.db.transaction():
            await self.db.create_sect(name, doc.uid, time.time())
            await self.db.save_player(d.model_dump())
        yield event.plain_result(
            f"【{name}】立宗成功！道友为开派宗主。\n"
            f"立宗花费 {sect.CREATE_COST} 灵石，当前等级：{sect.level_title(1)}（{sect.member_limit(1)} 人上限）"
        )

    @filter.command(CMD_SECT_JOIN, "加入宗门")
    async def handle_sect_join(self, event: AstrMessageEvent, name: str = ""):
        if not self._allowed(event):
            return
        doc, err = await self._require_player(event)
        if err:
            yield event.plain_result(err)
            return
        if doc.ext.get("sect"):
            yield event.plain_result("道友已有宗门，先「#退出宗门」再投他派。")
            return
        name = (name or "").strip()
        target = await self.db.get_sect(name)
        if not target:
            yield event.plain_result(f"查无此宗：「{name}」。可发「{CMD_SECT_LIST}」查看。")
            return
        # W8-F7 宗主设下的加入门槛（原版「#设置门槛」的消费者）
        _cal = await self.db.get_calamity()
        _gate = sec_mod.gate_of((_cal.get("sect_deep") or {}).get(name) or {})
        if _gate and doc.realm_index + 1 < _gate:
            yield event.plain_result(
                f"【{name}】设下门槛：需第 {_gate} 境，道友尚在第 {doc.realm_index + 1} 境。")
            return
        members = await self._sect_members(name)
        limit = sect.member_limit(target["level"])
        if len(members) >= limit:
            yield event.plain_result(f"【{name}】人满（{len(members)}/{limit}），升级宗门可扩员。")
            return
        d = doc.model_copy(deep=True)
        d.ext["sect"] = name
        await self.db.save_player(d.model_dump())
        yield event.plain_result(f"道友已入【{name}】门墙（{len(members) + 1}/{limit}）。")

