    # ------------------------------------------------ W17-F1：位面大事件

    async def _pe_save(self, doc: PlayerDoc, delta: dict | None = None,
                       calamity: dict | None = None):
        async with self.db.transaction():
            await self.db.save_player(doc.model_dump())
            for name, qty in (delta or {}).items():
                if qty > 0:
                    await self.db.add_items(doc.uid, {name: qty})
                elif qty < 0:
                    await self.db.remove_item(doc.uid, name, -qty)
            if calamity is not None:
                await self.db.save_calamity(calamity)

    _BTN_MSGS: dict = {}          # 按钮点击事件的合成指令串（id(event) → str）

    def _msg_of(self, event: AstrMessageEvent) -> str:
        """按钮点击事件带合成指令串（分发器注入），文本消息原样返回。"""
        injected = self._BTN_MSGS.get(id(event))
        return str(injected) if injected else str(getattr(event, "message_str", "") or "")

    def _daily_sign_rows(self):
        """W33：原版 DAILY_SIGN_BUTTONS（去巡界——port 无该指令）。"""
        acts = [("修仙签到", CMD_SIGN), ("天道赐福", CMD_TIANDAO),
                ("道法赐福", CMD_DAOFA_GIFT), ("垂纶", CMD_FISH_SIGN),
                ("星海之缘", CMD_AC_XH), ("每日抽奖", CMD_LOTTERY)]
        return _uk_row([_uk_btn("page.cmd", name, a1=cmd) for name, cmd in acts],
                       fallback=" / ".join(cmd for _, cmd in acts), timeout=86400)

    def _kb(self, event: AstrMessageEvent, text: str, *rows):
        """W30：构造「短文本 + 按钮」结果（组件不可用自动降级纯文本）。"""
        if not _uk_avail():
            return None
        return _uk_kb(event, text, *rows)

    def _pl_lock(self, uid: str) -> asyncio.Lock:
        """审计修复6：per-uid 玩家档锁——读档→改→存的跨度内串行，防整档覆盖。"""
        locks = getattr(self, "_player_locks", None)
        if locks is None:
            locks = self._player_locks = {}
        return locks.setdefault(str(uid), asyncio.Lock())

