    @filter.regex(r"^#若陀龙王分配(\d+)$")
    async def handle_dr_assign_bare(self, event: AstrMessageEvent):
        """原版 `^#若陀龙王分配.*$`：注意帮助 yaml 误抄成末尾带 `$`。"""
        import re as _re
